<script setup>import{onMounted,ref,computed}from'vue';import{useRoute,useRouter}from'vue-router';import{studentApi,formatTime,submissionNames}from'../../api/student';const route=useRoute(),router=useRouter(),exam=ref(),error=ref(''),busy=ref(false);onMounted(async()=>{try{exam.value=(await studentApi.exam(route.params.examId)).data}catch(e){error.value=e.message}});const buttonText=computed(()=>exam.value?.submissionStatus==='IN_PROGRESS'?'继续答题':'进入考试');async function enter(){busy.value=true;error.value='';try{const p=(await studentApi.enter(exam.value.id)).data;router.push('/student/paper/'+p.submissionId)}catch(e){error.value=e.message}finally{busy.value=false}}</script>
<template><p><RouterLink to="/student">← 返回考试列表</RouterLink></p><p v-if="error" class="error-message">{{error}}</p><article v-if="exam" class="surface"><div class="section-head"><div><p class="eyebrow">EXAM DETAIL</p><h1>{{exam.title}}</h1></div><span v-if="exam.submissionStatus" class="badge">{{submissionNames[exam.submissionStatus]}}</span></div><p class="preserve">{{exam.description||'暂无考试说明'}}</p><div class="meta-strip"><span>课程：{{exam.courseName}}</span><span>题目：{{exam.questionCount}} 道</span><span>考试：{{formatTime(exam.startTime)}} 至 {{formatTime(exam.endTime)}}</span><span>最早交卷：开考 {{exam.minSubmitMinutes}} 分钟后</span></div><p class="error-message">首次迟到超过 {{exam.lateEntryMinutes}} 分钟将无法入场；已进入且仍在答题中的答卷可以重新进入。</p><button v-if="!exam.submissionStatus||exam.submissionStatus==='IN_PROGRESS'" class="primary" :disabled="busy" @click="enter">{{busy?'正在进入…':buttonText}}</button><p v-else>该答卷已经提交，不能继续作答。</p></article></template>
